const byId = Object.fromEntries(works.map(w=>[w.id,w]));
const main=document.querySelector('#main');
const menu=document.querySelector('#menu');
let locale='ru', page='home', detail='', params=new URLSearchParams(), visible=6, toastTimer;
let collection;
try {
 const stored=JSON.parse(localStorage.getItem('unfold.collection.v1'));
 collection=Array.isArray(stored)?stored.filter(id=>byId[id]):['C02','S02'];
} catch { collection=['C02','S02']; }
collection=[...new Set(collection)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>copy[locale][k]??k;
const title=w=>w.titles[locale];
const artist=id=>artists.find(a=>a.id===id);
const fig=(id,alt='',cls='',attrs='loading="lazy" decoding="async"')=>`<img src="assets/figma/${id}.webp" alt="${esc(alt)}" class="${cls}" ${attrs}>`;
const picture=(w,cls='',src='',eager=false)=>{
 const full=eager&&src===w.image&&w.preview;
 const source=full?w.preview:(src||w.thumbnail||w.image);
 const responsive=full?` srcset="${w.thumbnail} ${w.thumbnail_width}w, ${w.preview} ${w.preview_width}w" sizes="(max-width:700px) calc(100vw - 48px), (max-width:1440px) 65vw, 940px"`:'';
 return `<img src="${esc(source)}"${responsive} alt="${esc(title(w)+' — '+w.artist_display)}" class="${cls}" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''} decoding="async" width="${w.width}" height="${w.height}">`;
};
function url(target='home',id='',query={}) {const q=new URLSearchParams(query).toString();return `#/${locale}/${target}${id?'/'+encodeURIComponent(id):''}${q?'?'+q:''}`;}
const link=(target,text,id='',cls='',query={})=>`<a class="${cls}" href="${url(target,id,query)}">${text}</a>`;
const arrow=' <span aria-hidden="true">→</span>';
const noteDecoration=()=>({artists:'<img src="assets/figma/022.svg" class="note-decoration artists-deco" alt="">',archive:'<img src="assets/figma/029.svg" class="note-decoration archive-deco" alt="">',collection:'<img src="assets/figma/035.svg" class="note-decoration collection-deco" alt="">',about:'<img src="assets/figma/036.svg" class="note-decoration about-deco-one" alt=""><img src="assets/figma/037.svg" class="note-decoration about-deco-two" alt="">'}[page]||'');
const note=(ru,en,cls='')=>`<p class="handwritten ${cls}">${esc(locale==='ru'?ru:en).replaceAll('\n','<br>')}</p>`;
const bookmark=(w,overlay=false)=>`<button class="bookmark ${overlay?'on-image':''} ${collection.includes(w.id)?'is-saved':''}" data-save="${w.id}" aria-pressed="${collection.includes(w.id)}" aria-label="${esc((collection.includes(w.id)?t('remove'):t('save'))+': '+title(w))}"><svg viewBox="0 0 20 24" width="20" height="24" aria-hidden="true"><path d="M3 2h14v19l-7-5-7 5z"/></svg></button>`;
function footer(back='') {return `<footer class="footer"><span>${t('footer')}</span>${back?link('catalog','← '+t('backExhibitions')):'<button data-top>'+t('top')+' ↑</button>'}</footer>`;}
function header(){
 const active=page==='exhibition'?'catalog':page==='artist'?'artists':page==='work'?'catalog':page;
 document.querySelector('#header').innerHTML=`<div class="header-inner">${link('home','UNFOLD','','brand')}<nav class="desktop-nav" aria-label="${locale==='ru'?'Основная навигация':'Main navigation'}">${['catalog','artists','archive','about'].map(p=>link(p,t(p),'',active===p?'active':'')).join('')}</nav><div class="languages" aria-label="Language"><a href="${languageUrl('en')}" lang="en" ${locale==='en'?'aria-current="true" class="active"':''}>EN</a><span>/</span><a href="${languageUrl('ru')}" lang="ru" ${locale==='ru'?'aria-current="true" class="active"':''}>RU</a></div><a href="${url('archive','',{search:'1'})}" class="header-search" aria-label="${esc(t('search'))}"><img src="assets/figma/008.webp" width="18" height="18" alt=""><span></span></a>${link('collection',`${t('collection')} <span data-count>(${collection.length})</span>`,'','collection-link')}${themeToggleMarkup(locale)}<button class="menu-button" data-menu aria-label="${t('menu')}" aria-haspopup="dialog"><img src="assets/figma/009.webp" width="18" height="18" alt=""></button></div>`;
}
function languageUrl(lang){return `#/${lang}/${page}${detail?'/'+encodeURIComponent(detail):''}${params.size?'?'+params.toString():''}`;}
function breadcrumb(items){return `<nav class="breadcrumbs" aria-label="${locale==='ru'?'Навигационная цепочка':'Breadcrumb'}">${items.map(([p,label,id],i)=>p?link(p,esc(label),id):`<span aria-current="page">${esc(label)}</span>`).join('<span aria-hidden="true"> / </span>')}</nav>`;}
function home(){
 const cards=[['P01','004',locale==='ru'?'Работа в фокусе':'Featured work',locale==='ru'?'Волны — Pierre Châtel-Innocenti.':'Waves — Pierre Châtel-Innocenti.','work','P01'],['S04','005',locale==='ru'?'Контекст':'Context',locale==='ru'?'Природа, узоры и наблюдения.':'Nature, patterns and observation.','exhibition','glass'],['P01','006',locale==='ru'?'Фрагменты':'Fragments',locale==='ru'?'Детали работы «Волны».':'Details of Waves.','work','P01'],['C02','007',locale==='ru'?'Новые работы':'Latest additions',locale==='ru'?'Недавно в UNFOLD.':'Newly added to UNFOLD.','archive','']];
 return `<div class="home-page"><section class="hero" aria-labelledby="hero-title"><div class="hero-art"><a class="hero-fluid" href="${url('work','C03')}">${fig('001',title(byId.C03)+' — Pawel Czerwinski','','loading="eager" decoding="async"')}</a><a class="hero-building" href="${url('work','P05')}">${fig('002',title(byId.P05)+' — Pierre Châtel-Innocenti','','loading="eager" fetchpriority="high" decoding="async"')}</a><a class="hero-paper" href="${url('work','F03')}">${fig('003',title(byId.F03)+' — Fons Heijnsbroek','','loading="eager" decoding="async"')}</a></div><p class="eyebrow">${locale==='ru'?'Цифровая выставка':'Digital art exhibition'}<span></span></p><h1 id="hero-title">UNFOLD</h1><p class="hero-description">${locale==='ru'?'В каждой работе —<br>больше одного слоя.':'Every artwork has more<br>than one layer.'}</p>${link('archive',`<span class="circle-arrow" aria-hidden="true">→</span><span>${t('openArchive')}</span><i></i>`,'','hero-cta')}${note('Один образ.\nРазные истории.','The same image.\nDifferent stories.','hero-note')}${fig('010','','hero-scribble')}<div class="hero-index"><span>${locale==='ru'?'Искусство':'Art'}</span><div>${[locale==='ru'?'Фрагменты':'Fragments',locale==='ru'?'Заметки':'Notes',locale==='ru'?'Связи':'Connections'].map(x=>`<span>${x}</span>`).join('')}</div><span>+</span></div></section><section class="featured container" aria-labelledby="featured-title"><div class="section-kicker"><h2 id="featured-title">${locale==='ru'?'В фокусе выставки':'Featured in the exhibition'}</h2>${link('catalog',(locale==='ru'?'Смотреть всё':'Explore all')+arrow)}</div><div class="featured-grid">${cards.map(([id,img,label,desc,target,extra])=>`<article>${link(target,fig(img,title(byId[id]))+`<h3>${label}${arrow}</h3><p>${desc}</p>`,extra,'featured-card')}</article>`).join('')}</div></section></div>`;
}
function exCard(ex,large=false){const names=ex.artists.length===1?artist(ex.artists[0]).name:(locale==='ru'?'2 автора':'2 artists');return `<article class="ex-card ${large?'ex-featured':''}"><a class="ex-image" href="${url('exhibition',ex.id)}">${fig(ex.cover,ex.title[locale],'',large?'fetchpriority="high"':'loading="lazy"')}${large?`<span class="image-number">${ex.number}</span>`:''}</a><div class="ex-copy">${large?'':`<span class="ex-number">${ex.number}</span>`}<div><h2>${link('exhibition',esc(ex.title[locale]),ex.id)}</h2><p class="metadata">${esc(names)} · 6 ${locale==='ru'?'работ':'works'}${ex.id==='surface'?' · '+(locale==='ru'?'фото / живопись':'photo / paint'):''}</p><p>${esc(ex.description[locale])}</p>${link('exhibition',t('viewExhibition')+arrow,ex.id,'text-link')}</div></div></article>`;}
function catalog(){const filter=params.get('medium')||'all';const filtered=exhibitions.filter(e=>filter==='all'||e.category===filter);return `<div class="container catalog-page">${breadcrumb([['home',t('home')],[null,t('catalog')]])}<section class="catalog-heading"><h1>${t('catalog')}</h1><p>${locale==='ru'?'Настоящие авторы.<br>Избранные работы.<br>Новые взгляды.':'Real artists.<br>Selected works.<br>New perspectives.'}</p>${note('Найди свою\nновую историю.','Find your\nnext story.')}${fig('017','','catalog-arrow')}</section><nav class="filter-tabs" aria-label="${t('medium')}">${['all','photography','painting','mixed'].map(v=>link('catalog',t(v),'',filter===v?'active':'',v==='all'?{}:{medium:v})).join('')}<span>${filtered.length} ${locale==='ru'?'выставок':'exhibitions'}</span></nav>${filter==='all'?`<div class="catalog-top">${exCard(exhibitions[0],true)}<div class="catalog-side">${exCard(exhibitions[1])}${exCard(exhibitions[2])}</div></div><div class="catalog-bottom">${exhibitions.slice(3).map(e=>exCard(e)).join('')}</div>`:`<div class="filtered-exhibitions">${filtered.map(e=>exCard(e)).join('')}</div>`}<div class="list-end"><p>${locale==='ru'?`Показано ${filtered.length} из ${filtered.length} выставок`:`Showing ${filtered.length} of ${filtered.length} exhibitions`}</p>${link('archive',t('openArchive')+arrow,'','outline-button')}</div>${footer()}</div>`;}
function pageHeading(heading,count,ru,en,description,cls=''){return `<section class="page-heading ${cls}"><div class="heading-line"><h1>${esc(heading)}</h1>${count!==null?`<span class="display-count">${String(count).padStart(2,'0')}</span>`:''}</div>${note(ru,en)}${noteDecoration()}${description?`<p class="page-description">${esc(description)}</p>`:''}</section>`;}
function artistsPage(){return `<div class="container artists-page">${pageHeading(t('artists'),4,'У каждого автора\nсвой взгляд.','Every artist has\na point of view.',locale==='ru'?'Знакомься с авторами произведений.':'Meet the people behind the works.')}<div class="artist-grid">${artists.map((a,i)=>`<article class="artist-card">${link('artist',fig(a.cover,a.name)+`<span class="image-number">0${i+1}</span>`,a.id,'artist-image')}<h2>${link('artist',esc(a.name),a.id)}</h2><p class="metadata">${esc(a.field[locale])}</p>${link('artist',t('viewArtist')+arrow,a.id,'text-link')}</article>`).join('')}</div>${footer()}</div>`;}
function searchControls(isCollection=false){const q=params.get('q')||'',selected=params.get('artist')||'',medium=params.get('medium')||'',sort=params.get('sort')||(isCollection?'saved':'curated');return `<div class="search-controls"><label class="search-field"><img src="assets/figma/030.webp" width="30" height="30" alt=""><span class="sr-only">${t(isCollection?'searchCollection':'search')}</span><input type="search" id="work-search" placeholder="${t(isCollection?'searchCollection':'search')}" value="${esc(q)}" autocomplete="off"></label><div class="select-row"><label><span class="sr-only">${t('artist')}</span><select data-filter="artist" aria-label="${t('artist')}"><option value="">${t('artist')}: ${t('allArtists')}</option>${artists.map(a=>`<option value="${a.id}" ${selected===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label><span class="sr-only">${t('medium')}</span><select data-filter="medium" aria-label="${t('medium')}"><option value="">${t('medium')}: ${t('allMedia')}</option>${['photography','painting','mixed'].map(v=>`<option value="${v}" ${medium===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><label class="sort-select"><span class="sr-only">${t('sort')}</span><select data-filter="sort" aria-label="${t('sort')}">${[isCollection?'saved':'curated','newest','oldest','alphabet'].map(v=>`<option value="${v}" ${v===sort?'selected':''}>${t(v==='saved'?'recentSaved':v)}</option>`).join('')}</select></label></div></div>`;}
function filteredWorks(isCollection=false){let result=(isCollection?collection:archiveOrder).map(id=>byId[id]);const q=(params.get('q')||'').trim().toLocaleLowerCase(locale);const a=params.get('artist'),medium=params.get('medium');if(q)result=result.filter(w=>[w.titles.ru,w.titles.en,w.artist_display,w.title,w.medium].some(v=>v.toLocaleLowerCase(locale).includes(q)));if(a)result=result.filter(w=>w.artistId===a);if(medium)result=result.filter(w=>w.category===medium);const sort=params.get('sort');if(sort==='alphabet')result.sort((a,b)=>title(a).localeCompare(title(b),locale));if(sort==='newest'||sort==='oldest')result.sort((a,b)=>(a.date.localeCompare(b.date))*(sort==='newest'?-1:1));return result;}
function workCard(w,context='archive',source=''){const custom=source||(context==='archive'&&archiveImages[w.id]?`assets/figma/${archiveImages[w.id]}.webp`:context==='collection'&&['C02','S02'].includes(w.id)?`assets/figma/${w.id==='C02'?'032':'033'}.webp`:'');return `<article class="work-card"><div class="work-image">${link('work',picture(w,'',custom),w.id)}${context==='exhibition'?bookmark(w,true):''}</div><div class="work-card-heading"><h3>${link('work',esc(title(w))+(context==='exhibition'?arrow:''),w.id)}</h3>${context!=='exhibition'?bookmark(w):''}</div><p class="artist-name">${link('artist',esc(w.artist_display),w.artistId)}</p>${context!=='exhibition'?`<p class="metadata">${t(w.category)}</p>`:''}</article>`;}
function countPhrase(n,saved=false){if(locale==='en')return `${n} ${saved?'saved ':''}${n===1?'work':'works'}`;const form=n%10===1&&n%100!==11?'работа':[2,3,4].includes(n%10)&&![12,13,14].includes(n%100)?'работы':'работ';return `${n} ${saved?'сохранённ'+(form==='работа'?'ая':form==='работы'?'ые':'ых')+' ':''}${form}`;}
function archive(isCollection=false){const count=isCollection?collection.length:works.length;return `<div class="container ${isCollection?'collection':'archive'}-page">${pageHeading(t(isCollection?'collection':'archive'),count,isCollection?'Сохрани то,\nчто отзывается.':'Найди то,\nчто отзывается.',isCollection?'Keep what\nspeaks to you.':'Find what\nspeaks to you.',isCollection?(locale==='ru'?'Избранные работы. Твои собственные связи.':'Saved works. Your own connections.'):(locale==='ru'?'Исследуй работы. Находи свои связи.':'Explore every work. Find your own connections.'))}${searchControls(isCollection)}<section id="work-results" aria-label="${esc(t('works'))}" aria-live="polite">${results(isCollection)}</section>${footer()}</div>`;}
function results(isCollection=false){const list=filteredWorks(isCollection),items=list.slice(0,visible);const emptyCollection=isCollection&&!collection.length;return `<p class="result-count">${countPhrase(list.length,isCollection)}</p>${list.length?`<div class="work-grid ${isCollection?'two-column':''}">${items.map(w=>workCard(w,isCollection?'collection':'archive')).join('')}</div><div class="list-end"><p>${locale==='ru'?`Показано ${items.length} из ${list.length} ${list.length%10===1&&list.length%100!==11?'работы':'работ'}`:`Showing ${items.length} of ${list.length} works`}</p>${items.length<list.length?`<button class="outline-button" data-more>${t('loadMore')} ↓</button>`:isCollection?link('archive',t('exploreArchive')+arrow,'','outline-button'):''}</div>`:`<div class="empty-state"><h2>${emptyCollection?t('empty'):t('nothing')}</h2><p>${emptyCollection?t('emptyBody'):t('noMatches')}</p>${emptyCollection?link('archive',t('openArchive')+arrow,'','outline-button'):`<button class="outline-button" data-reset>${t('reset')}</button>`}</div>`}`;}
function exhibitionPage(){const ex=exhibitions.find(e=>e.id===detail);if(!ex)return notFound();const items=ex.works.map(id=>byId[id]);return `<div class="container exhibition-page">${breadcrumb([['home',t('home')],['catalog',t('catalog')],[null,ex.title[locale]]])}<section class="exhibition-intro"><div><p class="accent metadata">${locale==='ru'?'Кураторская подборка':'Curated selection'} ${ex.number}</p><h1>${esc(ex.title[locale]).replace(ex.id==='space'?(locale==='ru'?' пространства':' space'):'\0',ex.id==='space'?'<br>'+(locale==='ru'?'пространства':'space'):'')}</h1></div><div class="exhibition-description"><p>${esc(ex.intro[locale])}</p><p class="metadata">${t(ex.category)} · ${ex.artists.length} ${locale==='ru'?(ex.artists.length===1?'автор':'автора'):(ex.artists.length===1?'artist':'artists')} · 6 ${locale==='ru'?'работ':'works'}</p><a class="text-link" href="#exhibition-works" data-scroll="exhibition-works">${t('exploreWorks')} ↓</a></div>${note(ex.note.ru,ex.note.en)}</section><div class="exhibition-banner">${ex.id==='space'?fig('041',ex.title[locale],'','fetchpriority="high"'):fig(ex.cover,ex.title[locale])}</div><section id="exhibition-works" class="exhibition-works"><div class="section-heading"><h2>${t('exhibitionWorks')}</h2><span class="metadata">6 ${locale==='ru'?'работ':'works'}</span></div><div class="work-grid">${items.map((w,i)=>workCard(w,'exhibition',ex.id==='space'?`assets/figma/${['043','045','046','047','048','049'][i]}.webp`:'')).join('')}</div></section><div class="list-end"><p>${locale==='ru'?'Показано 6 из 6 работ':'Showing 6 of 6 works'}</p>${link('archive',t('openArchive')+arrow,'','outline-button')}</div><section class="more-artists"><h2>${t('moreArtists')}</h2><div>${artists.map(a=>link('artist',esc(a.name),a.id)).join('')}</div></section>${footer(true)}</div>`;}
function mediumDetail(w){const map={'Photography':['Фотография','Photography'],'Gouache on paper':['Гуашь на бумаге','Gouache on paper'],'Acrylic on paper':['Акрил на бумаге','Acrylic on paper'],'Gouache and a cut-and-glued form on paper':['Гуашь и бумажная аппликация','Gouache and paper collage'],'Gouache and ink on paper':['Гуашь и тушь на бумаге','Gouache and ink on paper']};return map[w.medium]?.[locale==='ru'?0:1]||w.medium;}
function workDescription(w){if(w.id==='P01')return locale==='ru'?'Белые балконы складываются в волнообразный ритм. Изгибы, тени и небольшие детали превращают здание в исследование формы.':'White balconies repeat in wave-like bands. Curves, shadows and small details turn a building into a study of rhythm.';return artist(w.artistId).description[locale];}
function workPage(){const w=byId[detail];if(!w)return notFound();const ex=exhibitions.find(e=>e.artists.length===1&&e.artists[0]===w.artistId);const related=works.filter(v=>v.artistId===w.artistId&&v.id!==w.id).slice(0,2);const isCreation=w.date_kind==='creation year';const dateLabel=isCreation?t('created'):w.date_kind.includes('publication')?t('published'):(locale==='ru'?'Дата записи источника':'Source record date');const displayDate=!isCreation?new Intl.DateTimeFormat(locale==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(w.date)):w.date.slice(0,4);return `<div class="container artwork-page">${breadcrumb([['home',t('home')],['catalog',t('catalog')],['exhibition',ex.title[locale],ex.id],[null,title(w)]])}<section class="artwork-heading"><h1 class="${title(w).length>15?'long-title':''}">${esc(title(w))}</h1>${note('Посмотри\nвнимательнее.','Look a little\ncloser.')}${fig('017','','work-note-arrow')}<span class="accent metadata">${t('work')} ${String(ex.works.indexOf(w.id)+1).padStart(2,'0')} / 06</span>${link('exhibition','← '+t('backExhibition'),ex.id,'artwork-back')}</section><div class="artwork-main"><a class="artwork-full" href="${w.image}" target="_blank" rel="noopener" aria-label="${esc(title(w)+(locale==='ru'?' — открыть изображение':' — open image'))}">${picture(w,'',w.id==='P01'?'assets/figma/050.webp':w.image,true)}</a><aside class="artwork-info"><h2>${link('artist',esc(w.artist_display).replace(w.artistId==='P'?' ':'\0',w.artistId==='P'?'<br>':' '),w.artistId)}</h2><p class="metadata">${mediumDetail(w)}</p>${w.id==='P01'?`<p>${locale==='ru'?'Жантийи, Франция':'Gentilly, France'}</p>`:''}<p>${dateLabel} ${esc(displayDate)}</p><div class="work-description"><h3 class="metadata">${t('workAbout')}</h3><p>${esc(workDescription(w))}</p></div><button class="outline-button save-work" data-save="${w.id}" aria-pressed="${collection.includes(w.id)}"><svg viewBox="0 0 20 24" width="13" height="16" aria-hidden="true"><path d="M3 2h14v19l-7-5-7 5z" fill="${collection.includes(w.id)?'currentColor':'none'}" stroke="currentColor"/></svg> ${collection.includes(w.id)?t('saved'):t('save')}</button><div class="work-credit"><p>${esc(w.credit)}</p><p><a href="${esc(w.source_url)}" target="_blank" rel="noopener">${t('source')} ↗</a> · <a href="${esc(w.license_url)}" target="_blank" rel="noopener">${esc(w.license)} ↗</a></p><details><summary>${locale==='ru'?'Название и источник':'Title and source'}</summary><p>${t('displayTitle')}: ${esc(title(w))}</p><p>${t('originalTitle')}: ${esc(w.title)}</p>${w.title_status.includes('descriptive')?`<p>${locale==='ru'?'Описательное название для навигации; это не подтверждённое авторское название.':'A descriptive navigation title, not a verified artist title.'}</p>`:''}</details></div></aside></div><section class="related-works"><h2>${t('otherWorks')}</h2><div class="work-grid two-column">${related.map((v,i)=>workCard(v,'related',w.id==='P01'?`assets/figma/${i?'052':'051'}.webp`:'')).join('')}</div></section>${footer()}</div>`;}
function artistPage(){const a=artist(detail);if(!a)return notFound();const list=works.filter(w=>w.artistId===a.id);return `<div class="container artist-detail">${breadcrumb([['home',t('home')],['artists',t('artists')],[null,a.name]])}<section class="artist-detail-heading"><p class="metadata accent">${esc(a.field[locale])}</p><h1>${esc(a.name)}</h1><p>${esc(a.description[locale])}</p>${link('archive',t('exploreArchive')+arrow,'','text-link',{artist:a.id})}</section><div class="work-grid">${list.map(w=>workCard(w)).join('')}</div>${footer()}</div>`;}
function about(){const steps=[['catalog',locale==='ru'?'Открывай работы,<br>объединённые общей темой.':'Discover works brought<br>together by a shared theme.'],['artists',locale==='ru'?'Знакомься с авторами<br>произведений.':'Meet the people behind<br>the works.'],['archive',locale==='ru'?'Исследуй работы<br>и следуй любопытству.':'Browse every work and<br>follow your curiosity.'],['collection',locale==='ru'?'Сохраняй работы,<br>к которым хочется вернуться.':'Save the works you want<br>to return to.']];return `<div class="container about-page">${pageHeading(t('about'),null,'Всегда есть\nчто рассмотреть.','There is always\nmore to see.',locale==='ru'?'Пространство для внимательного взгляда.':'A space for looking closer.')}<section class="about-idea"><div class="idea-copy"><p class="metadata accent">${locale==='ru'?'Идея UNFOLD':'The idea behind UNFOLD'}</p><h2>${locale==='ru'?'Искусство —<br>больше<br>одного слоя.':'Art, in more<br>than one<br>layer.'}</h2><p>${locale==='ru'?'UNFOLD — цифровое пространство фотографии и абстрактного искусства. Открывай работы разных авторов, замечай детали и находи собственные связи.':'UNFOLD is a digital space for exploring photography and abstract art. Discover works by different artists, notice the details, and find connections of your own.'}</p><p>${locale==='ru'?'Посмотри на целое. Останься ради деталей.':'Look at the whole. Stay for the details.'}</p></div><div class="about-collage">${link('work',fig('038',title(byId.S02)+' — Samuel Zeller'),'S02','about-glass')}${link('work',fig('040',title(byId.C06)+' — Pawel Czerwinski'),'C06','about-fluid')}${link('work',fig('039',title(byId.F06)+' — Fons Heijnsbroek'),'F06','about-paint')}</div></section><section class="how-to"><h2>${locale==='ru'?'Как исследовать':'How to explore'}</h2><div class="how-to-grid">${steps.map(([p,desc],i)=>`<article><span class="accent display-small">0${i+1}</span><h3>${link(p,t(p))}</h3><p>${desc}</p>${link(p,'→','','step-arrow')}</article>`).join('')}</div></section><section class="sources"><h2>${locale==='ru'?'Авторы и источники':'Artists & sources'}</h2><div><p>${locale==='ru'?'В проекте представлены работы Pierre Châtel-Innocenti, Samuel Zeller, Fons Heijnsbroek и Pawel Czerwinski.<br>Источники изображений: Unsplash и Wikimedia Commons.<br>Источники и лицензии указаны рядом с работами.':'Featuring works by Pierre Châtel-Innocenti, Samuel Zeller, Fons Heijnsbroek and Pawel Czerwinski.<br>Image sources: Unsplash and Wikimedia Commons.<br>Source and license details accompany each work.'}</p><p class="project-note">${locale==='ru'?'UNFOLD — учебный кураторский проект. Подборки составлены для этого сайта и не являются официальными выставками авторов. Некоторые названия — описательные; оригинальные подписи доступны на страницах работ.':'UNFOLD is an independent student curatorial project. These selections were created for this website and are not official artist exhibitions. Some titles are descriptive; original captions are available on each work page.'}</p></div></section><section class="about-cta"><h2>${locale==='ru'?'Найди новую связь.':'Find your next connection.'}</h2>${link('archive',t('exploreArchive')+arrow,'','outline-button')}</section>${footer()}</div>`;}
function notFound(){return `<div class="container empty-state"><span class="accent">404</span><h1>${locale==='ru'?'Страница не найдена':'Page not found'}</h1>${link('home',t('home')+arrow,'','outline-button')}</div>`;}
function showToast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function persist(){try{localStorage.setItem('unfold.collection.v1',JSON.stringify(collection));return true;}catch{return false;}}
function updateResults(){const target=document.querySelector('#work-results');if(target){target.innerHTML=results(page==='collection');prepareContentReveal(target,{dynamic:true});}}
function updateBookmarkButtons(id){document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{const saved=collection.includes(id);b.setAttribute('aria-pressed',String(saved));b.classList.toggle('is-saved',saved);if(b.classList.contains('save-work'))b.innerHTML=`<svg viewBox="0 0 20 24" width="13" height="16" aria-hidden="true"><path d="M3 2h14v19l-7-5-7 5z" fill="${saved?'currentColor':'none'}" stroke="currentColor"/></svg> ${saved?t('saved'):t('save')}`;else b.setAttribute('aria-label',(saved?t('remove'):t('save'))+': '+title(byId[id]));});}
function toggleSave(id){if(!byId[id])return;const had=collection.includes(id);collection=had?collection.filter(v=>v!==id):[id,...collection];const stored=persist();document.querySelectorAll('[data-count]').forEach(n=>n.textContent=`(${collection.length})`);if(page==='collection'){document.querySelector('.display-count').textContent=String(collection.length).padStart(2,'0');updateResults();}else updateBookmarkButtons(id);showToast(stored?t(had?'removed':'added'):t('storageUnavailable'));}
function setParam(key,value){if(value)params.set(key,value);else params.delete(key);params.delete('search');history.replaceState(null,'',url(page,detail,Object.fromEntries(params)));visible=6;header();updateResults();}
function showMenu(){menu.innerHTML=`<div class="menu-top"><span>UNFOLD</span><button data-close aria-label="${t('close')}">×</button></div><nav>${['home','catalog','artists','archive','collection','about'].map(p=>link(p,t(p))).join('')}</nav><div class="menu-languages"><a href="${languageUrl('en')}">EN</a> / <a href="${languageUrl('ru')}">RU</a></div>`;menu.showModal();document.body.classList.add('modal-open');}
function closeMenu(){if(menu.open)menu.close();document.body.classList.remove('modal-open');}
function render(){closeMenu();const [path,q='']=location.hash.replace(/^#\//,'').split('?');const parts=path.split('/');locale=parts[0]==='en'?'en':'ru';page=parts[1]||'home';detail=decodeURIComponent(parts[2]||'');params=new URLSearchParams(q);visible=6;document.documentElement.lang=locale;document.querySelector('#skip').textContent=locale==='ru'?'К содержимому':'Skip to content';header();const renderers={home,catalog,artists:artistsPage,archive:()=>archive(false),collection:()=>archive(true),about,exhibition:exhibitionPage,work:workPage,artist:artistPage};const hydrate=main.dataset.prerender==='ru-home'&&locale==='ru'&&page==='home';if(!hydrate)main.innerHTML=(renderers[page]||notFound)();main.removeAttribute('data-prerender');document.documentElement.dataset.initialView='ready';document.querySelector('#site-loading')?.remove();document.title=`${page==='work'&&byId[detail]?title(byId[detail]):page==='exhibition'?exhibitions.find(e=>e.id===detail)?.title[locale]||t('catalog'):page==='artist'?artist(detail)?.name||t('artists'):t(page)} / UNFOLD`;window.scrollTo({top:0,behavior:'instant'});syncExperienceChrome(locale);prepareContentReveal(main,{dynamic:hydrate});if(params.get('search'))document.querySelector('#work-search')?.focus();}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.tagName==='A'&&el.closest('#menu'))closeMenu();if(el.id==='skip'){e.preventDefault();main.focus();return;}if(el.hasAttribute('data-save')){e.preventDefault();toggleSave(el.dataset.save);}if(el.hasAttribute('data-menu'))showMenu();if(el.hasAttribute('data-close'))closeMenu();if(el.hasAttribute('data-top'))scrollToTop();if(el.hasAttribute('data-more')){visible+=6;updateResults();}if(el.hasAttribute('data-reset')){params=new URLSearchParams();history.replaceState(null,'',url(page));const input=document.querySelector('#work-search');if(input)input.value='';document.querySelectorAll('[data-filter]').forEach(s=>s.value=s.dataset.filter==='sort'?(page==='collection'?'saved':'curated'):'');visible=6;header();updateResults();}if(el.hasAttribute('data-scroll')){e.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth'});} });
document.addEventListener('input',e=>{if(e.target.id==='work-search')setParam('q',e.target.value);});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]'))setParam(e.target.dataset.filter,e.target.value);});
menu.addEventListener('click',e=>{if(e.target===menu)closeMenu();});menu.addEventListener('close',()=>document.body.classList.remove('modal-open'));
window.addEventListener('hashchange',render);
window.addEventListener('storage',e=>{if(e.key==='unfold.collection.v1'){try{const next=JSON.parse(e.newValue);if(Array.isArray(next)){collection=next.filter(id=>byId[id]);header();if(page==='collection')main.innerHTML=archive(true);else works.forEach(w=>updateBookmarkButtons(w.id));}}catch{}}});
if(!location.hash)history.replaceState(null,'','#/ru/home');
render();
